CHANGE['a2m-set'] = function(el){ ui('a2match', {})[el.getAttribute('data-k')] = el.value; };
ACT['a2m-run'] = function(){ var u = ui('a2match', {}), now = Date.now(), list = a2Orders().filter(function(o){ var a = a2O(o); return o.payment === 'cod' && a.cour === u.cour && (a.ost === 'DELIVERED' || a.ost === 'PARTIALLY_DELIVERED') && !a2Settled(o) && now - o.deliveredAt > 1.5 * A2.D; });
  if(!list.length) return toast(L('Nothing to match for this courier right now', 'এই কুরিয়ারের মেলানোর কিছু নেই'));
  var key = u.cour + ':' + a2dk(now); if(a2S().payouts.some(function(p){ return p.key === key; })) return toast(L('This file was matched already (same hash) — nothing doubled', 'এই ফাইল আগেই মেলানো হয়েছে'));
  var lines = list.map(function(o, i){ var fee = a2Rate(u.cour, o.zone) + Math.round(a2Goods(o) * .01), rec = o.total - fee, st = 'MATCHED', reason = ''; if(i === 0 && list.length > 2){ rec -= 100; st = 'MISMATCH'; reason = 'PARTIAL'; } return {order:o.id, exp:o.total, fee:fee, rec:rec, st:st, reason:reason}; });
  var po = {id:'PO-' + (600 + a2S().payouts.length), cour:u.cour, at:now, recv:u.recv, file:'statement-' + u.cour + '-' + a2dk(now) + '.csv', key:key, lines:lines, matchedAt:now};
  a2S().payouts.push(po); u.res = {id:po.id, matched:lines.filter(function(l){ return l.st === 'MATCHED'; }).length, mism:lines.filter(function(l){ return l.st === 'MISMATCH'; }).length, unmatched:1}; a2Log('Matched payout ' + po.id); saveState(); rerender(); };

