  return a2Head(ctx, {sub:Le('Refunds: requested by staff → approved by the owner → paid by Accounts. Nothing is paid by itself.', 'রিফান্ড: স্টাফ চায় → মালিক অনুমোদন দেন → হিসাব বিভাগ দেয়।')}) + a2Tabs(ctx) + owedBand + t + a2Mock(L('bKash, Nagad and card run on mock until their keys arrive', 'গেটওয়ে নকল মোডে')) + body;
